var catalogoReal = {};
try {
  var catData = $('Parsear Catalogo Equipos (DATA)').first().json;
  catalogoReal = (catData && catData.catalogoEquipos) ? catData.catalogoEquipos : {};
} catch (e) {}

function normalizarPlaca(p) { return String(p || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); }
function limpiarClave(s) { return String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); }

// ------------------------------------------------------------------
// BLINDAJE DE EQUIPOS SIN CÓDIGO (CORRECCIÓN #2)
// Necesario para que, al consolidar los registros de consumo, filas sin
// código (ej. una retroexcavadora identificada solo por su modelo: 95LR,
// B110, 310SJ, etc.) se agrupen bajo su código real y así /rutina_equipo
// CODIGO encuentre su acumulado correctamente.
// ------------------------------------------------------------------
var EQUIPOS_FALLBACK_KEYWORDS = [
  { keywords: ['95LR'], codigo: 'V13-010', placaDefault: 'N/A', descDefault: 'Retroexcavadora New Holland 95LR' },
  { keywords: ['B110'], codigo: 'V13-011', placaDefault: 'N/A', descDefault: 'Retroexcavadora New Holland B110' },
  { keywords: ['310SJ', '310 SJ'], codigo: 'V13-012', placaDefault: 'N/A', descDefault: 'Retroexcavadora Jhon Deere 310SJ' },
  { keywords: ['RETRO CASE', 'RETROCASE', 'CASE 580', 'CASE580'], codigo: 'V13-013', placaDefault: 'N/A', descDefault: 'Retroexcavadora CAse 580M' },
  { keywords: ['43RVAX', '43R VAX'], codigo: 'V10-004', placaDefault: '43R-VAX', descDefault: 'Camioneta Pick up Ranger' }
];

function normalizarTextoBusqueda(t) {
  return String(t || '').toUpperCase()
    .replace(/[ÁÀÄÂ]/g, 'A').replace(/[ÉÈËÊ]/g, 'E').replace(/[ÍÌÏÎ]/g, 'I')
    .replace(/[ÓÒÖÔ]/g, 'O').replace(/[ÚÙÜÛ]/g, 'U').replace(/Ñ/g, 'N')
    .replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function buscarEquipoPorPlacaODescripcion(placaFila, descFila) {
  var placaNorm = normalizarPlaca(placaFila);
  var textoCombinado = normalizarTextoBusqueda(String(placaFila || '') + ' ' + String(descFila || ''));

  if (placaNorm) {
    var matchPorPlaca = Object.keys(catalogoReal).find(function(k) {
      return normalizarPlaca(catalogoReal[k].placa) === placaNorm;
    });
    if (matchPorPlaca) {
      return { codigo: matchPorPlaca, placa: catalogoReal[matchPorPlaca].placa, descripcion: catalogoReal[matchPorPlaca].descripcion };
    }
  }
  if (textoCombinado) {
    var matchPorDesc = Object.keys(catalogoReal).find(function(k) {
      var cd = normalizarTextoBusqueda(catalogoReal[k].descripcion);
      return cd && (textoCombinado.indexOf(cd) !== -1 || cd.indexOf(textoCombinado) !== -1);
    });
    if (matchPorDesc) {
      return { codigo: matchPorDesc, placa: catalogoReal[matchPorDesc].placa, descripcion: catalogoReal[matchPorDesc].descripcion };
    }
  }
  for (var i = 0; i < EQUIPOS_FALLBACK_KEYWORDS.length; i++) {
    var regla = EQUIPOS_FALLBACK_KEYWORDS[i];
    var coincide = regla.keywords.some(function(kw) { return textoCombinado.indexOf(kw) !== -1; });
    if (coincide) {
      var catInfo = catalogoReal[regla.codigo];
      return {
        codigo: regla.codigo,
        placa: (catInfo && catInfo.placa) || regla.placaDefault,
        descripcion: (catInfo && catInfo.descripcion) || regla.descDefault
      };
    }
  }
  return null;
}

function obtenerInfoEquipo(codigo, placaFila, descFila) {
  var cod = String(codigo || '').toUpperCase().trim();
  if (cod === 'N/D' || cod === 'N D' || cod === 'ND' || cod === '-') cod = '';
  var placa = placaFila && String(placaFila).trim() !== '---------' ? String(placaFila).trim() : '';
  var desc = descFila || '';
  if (cod && catalogoReal[cod]) {
    placa = catalogoReal[cod].placa || placa;
    desc = catalogoReal[cod].descripcion || desc;
  }
  if (!cod) {
    var encontrado = buscarEquipoPorPlacaODescripcion(placa || placaFila, desc || descFila);
    if (encontrado) {
      cod = encontrado.codigo;
      placa = encontrado.placa || placa;
      desc = encontrado.descripcion || desc;
    }
  }
  return { codigo: cod || 'N/D', placa: placa || 'N/A', descripcion: desc || 'Sin descripción' };
}

function obtenerFechaReset(codigo, placa, descripcion) {
  var codClean = String(codigo || '').toUpperCase().trim();
  var codNorm = codClean.replace(/[^A-Z0-9]/g, '');
  var pNorm = normalizarPlaca(placa);

  if (codClean && resets[codClean]) return new Date(resets[codClean]);
  if (codNorm && resets[codNorm]) return new Date(resets[codNorm]);
  if (pNorm && resets[pNorm]) return new Date(resets[pNorm]);

  if (codClean && MANTENIMIENTOS_BASE[codClean]) return new Date(MANTENIMIENTOS_BASE[codClean]);
  if (codNorm && MANTENIMIENTOS_BASE[codNorm]) return new Date(MANTENIMIENTOS_BASE[codNorm]);
  if (pNorm && MANTENIMIENTOS_BASE[pNorm]) return new Date(MANTENIMIENTOS_BASE[pNorm]);

  var descUpper = String(descripcion || '').toUpperCase();
  for (var k in MANTENIMIENTOS_BASE) {
    if (k.length >= 3 && descUpper.indexOf(k) !== -1) return new Date(MANTENIMIENTOS_BASE[k]);
  }
  return null;
}

function clasificarEquipo(codigo, esTablaGasolina) {
  var cod = String(codigo || '').toUpperCase();
  if (cod.indexOf('V11-') === 0) {
    return { grupo: 'V11', tipo: 'PESADO', rendimiento: 3.5, limiteMtto: 10000, unidadMtto: 'Km' };
  } else if (cod.indexOf('V12-') === 0) {
    return { grupo: 'V12', tipo: 'ARRASTRE', rendimiento: 3.5, limiteMtto: 10000, unidadMtto: 'Km' };
  } else if (cod.indexOf('V13-') === 0) {
    return { grupo: 'V13', tipo: 'MAQUINARIA', rendimiento: 10, limiteMtto: 250, unidadMtto: 'Hrs' };
  } else if (cod.indexOf('V10-') === 0 || esTablaGasolina) {
    return { grupo: 'V10', tipo: 'LIVIANO', rendimiento: 3.5, limiteMtto: 7000, unidadMtto: 'Km' };
  }
  return { grupo: 'V11', tipo: 'PESADO', rendimiento: 3.5, limiteMtto: 10000, unidadMtto: 'Km' };
}

function estimarKmUHoras(litros, clasif) {
  if (!litros || litros <= 0) return 0;
  if (clasif.tipo === 'MAQUINARIA') return Math.round((litros / 10) * 10) / 10;
  return Math.round(litros * clasif.rendimiento);
}

function formatMiles(n) {
  var num = Math.round(Number(n) || 0);
  var signo = num < 0 ? '-' : '';
  var absStr = String(Math.abs(num));
  return signo + absStr.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

var idEquipoRutina = limpiarClave(params.idEquipoRutina);
var idEquipoOriginal = String(params.idEquipoRutina || '').toUpperCase().trim();

var equiposMap = {};

function procesarRegistro(h, esGasolina) {
  var cant = Number(h.combConsumido) || 0;
  if (cant <= 0) return;
  var info = obtenerInfoEquipo(h.codigo, h.placas, h.descripcion);
  var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);

  if (!equiposMap[key]) {
    equiposMap[key] = { codigo: info.codigo, descripcion: info.descripcion, placa: info.placa, esGasolina: esGasolina, litrosAcumulados: 0 };
  }

  var fechaReg = h.fecha ? new Date(h.fecha) : null;
  var fechaReset = obtenerFechaReset(info.codigo, info.placa, info.descripcion);

  var fResetTime = fechaReset ? new Date(fechaReset.getFullYear(), fechaReset.getMonth(), fechaReset.getDate()).getTime() : null;
  var fDiaTime = fechaReg ? new Date(fechaReg.getFullYear(), fechaReg.getMonth(), fechaReg.getDate()).getTime() : null;

  if (!fResetTime || (fDiaTime && fDiaTime >= fResetTime)) {
    equiposMap[key].litrosAcumulados += cant;
  }
}

(d.historialConsumosGasoil || []).forEach(function(h) { procesarRegistro(h, false); });
(d.historialConsumosGasolina || []).forEach(function(h) { procesarRegistro(h, true); });

var clasif = clasificarEquipo(idEquipoOriginal, false);

// Buscar el equipo puntual dentro de lo consolidado este mes (por codigo o placa normalizados)
var registroEquipo = null;
Object.keys(equiposMap).forEach(function(k) {
  if (registroEquipo) return;
  var eq = equiposMap[k];
  var codNorm = limpiarClave(eq.codigo);
  var placaNorm = normalizarPlaca(eq.placa);
  if (codNorm === idEquipoRutina || (placaNorm && placaNorm === idEquipoRutina)) {
    registroEquipo = eq;
  }
});

// Datos base del catalogo (por si el equipo no registro consumo este mes: acumulado 0)
var infoCatalogo = catalogoReal[idEquipoOriginal] || {};
var placaFinal = (registroEquipo && registroEquipo.placa && registroEquipo.placa !== 'N/A') ? registroEquipo.placa : (infoCatalogo.placa || 'N/A');
var descFinal = (registroEquipo && registroEquipo.descripcion && registroEquipo.descripcion !== 'Sin descripción') ? registroEquipo.descripcion : (infoCatalogo.descripcion || 'Sin descripción');

var litrosAcumulados = registroEquipo ? registroEquipo.litrosAcumulados : 0;
var acumulado = estimarKmUHoras(litrosAcumulados, clasif);
var acumuladoFmt = clasif.tipo === 'MAQUINARIA' ? acumulado.toFixed(1).replace('.', ',') : formatMiles(acumulado);
var limiteFmt = clasif.tipo === 'MAQUINARIA' ? clasif.limiteMtto.toFixed(1).replace('.', ',') : formatMiles(clasif.limiteMtto);

return [{
  json: Object.assign({}, params, {
    idEquipoRutina: idEquipoOriginal,
    familiaRutina: params.familiaRutina || clasif.grupo,
    placaEquipoRutina: placaFinal,
    descripcionEquipoRutina: descFinal,
    acumuladoEquipoRutina: acumulado,
    acumuladoEquipoRutinaFmt: acumuladoFmt,
    limiteMttoEquipoRutina: clasif.limiteMtto,
    limiteMttoEquipoRutinaFmt: limiteFmt,
    unidadMttoEquipoRutina: clasif.unidadMtto
  })
}];

