function hoyVenezuela() {
  try {
    var partesVET = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Caracas', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()).split('-');
    var fVET = new Date(parseInt(partesVET[0], 10), parseInt(partesVET[1], 10) - 1, parseInt(partesVET[2], 10));
    if (!isNaN(fVET.getTime())) return fVET;
  } catch (eVET) {}
  var ahoraSrv = new Date();
  return new Date(ahoraSrv.getFullYear(), ahoraSrv.getMonth(), ahoraSrv.getDate());
}
