function normalizarTextoBusqueda(t) {
  return String(t || '').toUpperCase()
    .replace(/[ÁÀÄÂ]/g, 'A').replace(/[ÉÈËÊ]/g, 'E').replace(/[ÍÌÏÎ]/g, 'I')
    .replace(/[ÓÒÖÔ]/g, 'O').replace(/[ÚÙÜÛ]/g, 'U').replace(/Ñ/g, 'N')
    .replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function buscarEquipoPorPlacaODescripcion(placaFila, descFila) {
  var placaNorm = normalizarPlaca(placaFila);
  var textoCombinado = normalizarTextoBusqueda(String(placaFila || '') + ' ' + String(descFila || ''));

  if (placaNorm) {
    var matchPorPlaca = Object.keys(catalogoReal).find(function(k) {
      return normalizarPlaca(catalogoReal[k].placa) === placaNorm;
    });
    if (matchPorPlaca) {
      return { codigo: matchPorPlaca, placa: catalogoReal[matchPorPlaca].placa, descripcion: catalogoReal[matchPorPlaca].descripcion };
    }
  }
  if (textoCombinado) {
    var matchPorDesc = Object.keys(catalogoReal).find(function(k) {
      var cd = normalizarTextoBusqueda(catalogoReal[k].descripcion);
      return cd && (textoCombinado.indexOf(cd) !== -1 || cd.indexOf(textoCombinado) !== -1);
    });
    if (matchPorDesc) {
      return { codigo: matchPorDesc, placa: catalogoReal[matchPorDesc].placa, descripcion: catalogoReal[matchPorDesc].descripcion };
    }
  }
  for (var i = 0; i < EQUIPOS_FALLBACK_KEYWORDS.length; i++) {
    var regla = EQUIPOS_FALLBACK_KEYWORDS[i];
    var coincide = regla.keywords.some(function(kw) { return textoCombinado.indexOf(kw) !== -1; });
    if (coincide) {
      var catInfo = catalogoReal[regla.codigo];
      return {
        codigo: regla.codigo,
        placa: (catInfo && catInfo.placa) || regla.placaDefault,
        descripcion: (catInfo && catInfo.descripcion) || regla.descDefault
      };
    }
  }
  return null;
}

function obtenerInfoEquipo(codigo, placaFila, descFila) {
  var cod = String(codigo || '').toUpperCase().trim();
  if (cod === 'N/D' || cod === 'N D' || cod === 'ND' || cod === '-') cod = '';
  var placa = placaFila && String(placaFila).trim() !== '---------' ? String(placaFila).trim() : '';
  var desc = descFila || '';
  if (cod && catalogoReal[cod]) {
    placa = catalogoReal[cod].placa || placa;
    desc = catalogoReal[cod].descripcion || desc;
  }
  if (!cod) {
    var encontrado = buscarEquipoPorPlacaODescripcion(placa || placaFila, desc || descFila);
    if (encontrado) {
      cod = encontrado.codigo;
      placa = encontrado.placa || placa;
      desc = encontrado.descripcion || desc;
    }
  }
  return { codigo: cod || 'N/D', placa: placa || 'N/A', descripcion: desc || 'Sin descripción' };
}

function obtenerFechaResetRaw(codigo, placa, descripcion) {
  var codClean = String(codigo || '').toUpperCase().trim();
  var codNorm = codClean.replace(/[^A-Z0-9]/g, '');
  var pNorm = normalizarPlaca(placa);

  if (codClean && resets[codClean]) return resets[codClean];
  if (codNorm && resets[codNorm]) return resets[codNorm];
  if (pNorm && resets[pNorm]) return resets[pNorm];

  if (codClean && catalogoReal[codClean] && catalogoReal[codClean].fechaMP) {
    return catalogoReal[codClean].fechaMP;
  }

  if (codClean && MANTENIMIENTOS_BASE[codClean]) return MANTENIMIENTOS_BASE[codClean];
  if (codNorm && MANTENIMIENTOS_BASE[codNorm]) return MANTENIMIENTOS_BASE[codNorm];
  if (pNorm && MANTENIMIENTOS_BASE[pNorm]) return MANTENIMIENTOS_BASE[pNorm];

  var descUpper = String(descripcion || '').toUpperCase();
  for (var k in MANTENIMIENTOS_BASE) {
    if (k.length >= 3 && descUpper.indexOf(k) !== -1) return MANTENIMIENTOS_BASE[k];
  }
  return null;
}

function formatFechaResetSegura(d) {
  if (!d) return 'INICIO 2026';
  if (typeof d === 'string') {
    var p = d.slice(0, 10).split('-');
    if (p.length === 3 && p[0].length === 4) return p[2] + '/' + p[1] + '/' + p[0];
  }
  if (d instanceof Date && !isNaN(d.getTime())) {
    var iso = d.toISOString().slice(0, 10).split('-');
    return iso[2] + '/' + iso[1] + '/' + iso[0];
  }
  return 'INICIO 2026';
}

function clasificarEquipo(codigo, esTablaGasolina) {
  var cod = String(codigo || '').toUpperCase();
  if (cod.indexOf('V11-') === 0) {
    return { grupo: 'V11', tituloGrupo: '🚛 VEHÍCULOS PESADOS (GASOIL)', tipo: 'PESADO', rendimiento: 3.5, limiteMtto: 10000, unidadMtto: 'Km' };
  } else if (cod.indexOf('V12-') === 0) {
    return { grupo: 'V12', tituloGrupo: '🚚 EQUIPOS DE TRANSPORTE / VACUM (GASOIL)', tipo: 'ARRASTRE', rendimiento: 3.5, limiteMtto: 10000, unidadMtto: 'Km' };
  } else if (cod.indexOf('V13-') === 0) {
