  } else if (cod.indexOf('V10-') === 0 || esTablaGasolina) {
    return { grupo: 'V10', tituloGrupo: '🚗 VEHÍCULOS LIVIANOS (GASOLINA)', tipo: 'LIVIANO', rendimiento: 3.5, limiteMtto: 7000, unidadMtto: 'Km' };
