function procesarRegistro(h, esGasolina) {
  var cant = Number(h.combConsumido) || 0;
  if (cant <= 0) return;
  var info = obtenerInfoEquipo(h.codigo, h.placas, h.descripcion);
  var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);

  if (!equiposMap[key]) {
    var fResetRaw = obtenerFechaResetRaw(info.codigo, info.placa, info.descripcion);
    equiposMap[key] = {
      codigo: info.codigo,
      descripcion: info.descripcion,
      placa: info.placa,
      esGasolina: esGasolina,
      litrosAcumulados: 0,
      fechaResetRaw: fResetRaw,
      fechaUltimoMtto: formatFechaResetSegura(fResetRaw)
    };
  }

  var fechaReg = h.fecha ? new Date(h.fecha) : null;
  var fReset = equiposMap[key].fechaResetRaw ? new Date(equiposMap[key].fechaResetRaw) : null;

  var fResetTime = fReset ? new Date(fReset.getFullYear(), fReset.getMonth(), fReset.getDate()).getTime() : null;
  var fDiaTime = fechaReg ? new Date(fechaReg.getFullYear(), fechaReg.getMonth(), fechaReg.getDate()).getTime() : null;

  if (!fResetTime || (fDiaTime && fDiaTime >= fResetTime)) {
    equiposMap[key].litrosAcumulados += cant;
  }
}

