var LIMITE_DIAS_POR_FAMILIA = { V10: 90, V11: 180, V12: 180 };
// Días desde el M/P medidos contra la fecha de la última planilla leída (no contra el reloj del servidor).
var hoyReferencia = REF_ALERTA.fecha;

var listaRojo = [];
var listaAmarillo = [];
var estadoActual = {};

Object.keys(equiposMap).forEach(function(k) {
  var eq = equiposMap[k];
  if (!eq.codigo || eq.codigo === 'N/D') return;

  var clasif = clasificarEquipo(eq.codigo, eq.esGasolina);
  var acumulado = estimarKmUHoras(eq.litrosAcumulados, clasif);
  var faltan = clasif.limiteMtto - acumulado;
  var pct = Math.round((acumulado / clasif.limiteMtto) * 1000) / 10;
  // Mismo cálculo de % que los informes HTML (entero, tope 100).
  var porcentajeMtto = Math.min(100, Math.round((acumulado / clasif.limiteMtto) * 100));

  // Días transcurridos desde el último M/P (V10: 90 · V11/V12: 180). V13 solo por horómetro.
  var CICLO_RECOMENDADO_DIAS = LIMITE_DIAS_POR_FAMILIA[clasif.grupo] || 180;
  var fechaBaseMtto = eq.fechaResetRaw ? new Date(eq.fechaResetRaw) : new Date(2026, 0, 1);
  var diasDesdeMtto = Math.max(0, Math.round((hoyReferencia.getTime() - fechaBaseMtto.getTime()) / 86400000));
  var porcentajeDias = Math.min(100, Math.round((diasDesdeMtto / CICLO_RECOMENDADO_DIAS) * 100));
  var superaCicloRecomendado = diasDesdeMtto > CICLO_RECOMENDADO_DIAS;
  var diasExcedidos = Math.max(0, diasDesdeMtto - CICLO_RECOMENDADO_DIAS);

  // UMBRAL UNIFICADO (idéntico a Informe Mensual/Anual y a /pendientes_mtto):
  // CRÍTICO si supera 100% de Km/Hrs O el límite de días.
  // ADVERTENCIA si alcanza 80% de Km/Hrs O de días.
  var aplicaControlPorDias = (clasif.grupo === 'V10' || clasif.grupo === 'V11' || clasif.grupo === 'V12');
  // UMBRALES UNIFICADOS (sobre el valor real, sin redondeo del %):
  //   V10 → CRÍTICO si Km >= 7.000 o Días > 90
  //   V11/V12 → CRÍTICO si Km >= 10.000 o Días > 180
  //   V13 → CRÍTICO si Horas >= 250 (solo horómetro, sin días)
  var superaPorKmHoras = acumulado >= clasif.limiteMtto;
  var superaPorDias = aplicaControlPorDias && superaCicloRecomendado;
  var enAdvertenciaPorKmHoras = acumulado >= clasif.limiteMtto * 0.8;
  var enAdvertenciaPorDias = aplicaControlPorDias && porcentajeDias >= 80;
  var esCritico = superaPorKmHoras || superaPorDias;
  var esAdvertencia = !esCritico && (enAdvertenciaPorKmHoras || enAdvertenciaPorDias);
  var porcentajeAlerta = aplicaControlPorDias ? Math.max(porcentajeMtto, porcentajeDias) : porcentajeMtto;

  var fila = {
    codigo: eq.codigo,
    descripcion: eq.descripcion,
    placa: eq.placa,
    grupo: clasif.grupo,
    tituloGrupo: clasif.tituloGrupo,
    tipo: clasif.tipo,
    acumulado: acumulado,
    limiteMtto: clasif.limiteMtto,
    unidadMtto: clasif.unidadMtto,
    pct: pct,
    faltan: faltan,
    porcentajeAlerta: porcentajeAlerta,
    porcentajeDias: porcentajeDias,
    diasDesdeMtto: diasDesdeMtto,
    cicloRecomendadoDias: CICLO_RECOMENDADO_DIAS,
    diasExcedidos: diasExcedidos,
    superaPorKmHoras: superaPorKmHoras,
    superaPorDias: superaPorDias,
    aplicaControlPorDias: aplicaControlPorDias,
    fechaUltimoMtto: eq.fechaUltimoMtto
  };

  if (esCritico) {
    listaRojo.push(fila);
    estadoActual[eq.codigo] = { estado: 'ROJO', acumulado: acumulado };
  } else if (esAdvertencia) {
    listaAmarillo.push(fila);
    estadoActual[eq.codigo] = { estado: 'AMARILLO', acumulado: acumulado };
  }
});

