// Reglas de envío (anti-spam 48h):
//  a) Equipo/evento NUEVO (no estaba en alerta en el último aviso).
//  b) ESCALÓ de 🟡 ADVERTENCIA a 🔴 CRÍTICO.
//  c) Pasaron más de 48h desde su último aviso y sigue sin resolverse.
listaRojo.concat(listaAmarillo).forEach(function(f) {
  var estadoNuevo = estadoActual[f.codigo].estado;
  var anterior = previo[f.codigo];
  var horasDesdeUltimoAviso = (anterior && anterior.ultimoAviso) ? (ahora - new Date(anterior.ultimoAviso)) / 3600000 : Infinity;
  if (!anterior) { hayMotivoDeEnvio = true; motivosEnvio.nuevos++; }
  else if (anterior.estado === 'AMARILLO' && estadoNuevo === 'ROJO') { hayMotivoDeEnvio = true; motivosEnvio.escalados++; }
  else if (horasDesdeUltimoAviso > COOLDOWN_HORAS) { hayMotivoDeEnvio = true; motivosEnvio.recordatorios++; }
});

if (!hayMotivoDeEnvio || (listaRojo.length === 0 && listaAmarillo.length === 0)) {
