function bloqueEquipo(f, esRojo) {
  var acumuladoFmt = f.tipo === 'MAQUINARIA' ? f.acumulado.toFixed(1).replace('.', ',') : formatMiles(f.acumulado);
  var limiteFmt = f.tipo === 'MAQUINARIA' ? f.limiteMtto.toFixed(1).replace('.', ',') : formatMiles(f.limiteMtto);
  var unidad = f.unidadMtto;
  var lineas = [];
  var nombre = f.codigo + ' — ' + f.descripcion + (f.placa && f.placa !== 'N/A' ? ' (' + f.placa + ')' : '');
  lineas.push((esRojo ? '🔴' : '🟡') + ' <b>' + nombre + '</b>');
  lineas.push('• Acumulado: <b>' + acumuladoFmt + ' ' + unidad + '</b> / Límite: ' + limiteFmt + ' ' + unidad + ' (' + f.pct.toFixed(1) + '%)');
  if (f.aplicaControlPorDias) {
    var detalleTiempo = f.superaPorDias
      ? '🔴 <b>Vencido (+' + f.diasExcedidos + ' días)</b>'
      : (f.diasDesdeMtto + ' días / Límite: ' + f.cicloRecomendadoDias + ' días (' + f.porcentajeDias.toFixed(1) + '%)');
    lineas.push('• Tiempo M/P: ' + detalleTiempo + ' · <i>Último: ' + (f.fechaUltimoMtto || 'INICIO 2026') + '</i>');
  }
  var accionTxt = textoAccionFamilia(f.grupo, f.codigo);
  lineas.push('• <b>Acción: ' + accionTxt + '</b>');
  return lineas.join('\n');
}

