function bloqueEquipoCompacto(f, esRojo) {
  var acumuladoFmt = f.tipo === 'MAQUINARIA' ? f.acumulado.toFixed(1).replace('.', ',') : formatMiles(f.acumulado);
  var limiteFmt = f.tipo === 'MAQUINARIA' ? f.limiteMtto.toFixed(1).replace('.', ',') : formatMiles(f.limiteMtto);
  var txt = (esRojo ? '🔴 ' : '🟡 ') + '<b>' + f.codigo + '</b>' + (f.placa && f.placa !== 'N/A' ? ' (' + f.placa + ')' : '') +
    ' — ' + acumuladoFmt + '/' + limiteFmt + ' ' + f.unidadMtto;
