    barsSvg += '<text x="' + xCenter.toFixed(1) + '" y="' + (yBar - 6).toFixed(1) + '" fill="#ffffff" font-size="11" font-weight="700" text-anchor="middle" font-family="sans-serif">' + val.toLocaleString(LOCALE_RX) + ' L</text>';
