function estimarKmUHoras(litros, clasif) {
  if (!litros || litros <= 0) return 0;
  if (clasif.tipo === 'MAQUINARIA') return Math.round((litros / 10) * 10) / 10;
  return Math.round(litros * clasif.rendimiento);
}

function estimarHorasSecundarias(litros, clasif) {
