        destino: (h.destinoViaje && h.destinoViaje !== '---------' && h.destinoViaje.trim() !== '') ? h.destinoViaje.trim() : 'BASE RX'
      });
    }
  }

  if (!equiposMap[key]) {
    var fResetRaw = obtenerFechaResetRaw(info.codigo, info.placa, info.descripcion);
    equiposMap[key] = {
      codigo: info.codigo,
