// ======================================================
// ROYAL EXPRESS C.A. - CALCULAR BALANCE SEMANAL
// ======================================================
var inputItems = $input.all();
var d = inputItems.length ? inputItems[0].json : {};

var hoy = new Date();
var ANCLA_SEMANA1 = new Date(2026, 0, 5);

function calcularNumeroSemana(fecha) {
  var diffMs = fecha.getTime() - ANCLA_SEMANA1.getTime();
  var diffDias = Math.floor(diffMs / 86400000);
  var numero = Math.floor(diffDias / 7) + 1;
  if (numero < 0) numero = 0;
  if (numero > 52) numero = 52;
  return numero;
}

function calcularRangoSemana(numeroSemana) {
  if (numeroSemana === 0) {
    return { inicio: new Date(2026, 0, 1), fin: new Date(2026, 0, 4) };
  }
  var inicio = new Date(ANCLA_SEMANA1.getTime() + (numeroSemana - 1) * 7 * 86400000);
  var fin = new Date(inicio.getTime() + 6 * 86400000);
  return { inicio: inicio, fin: fin };
}

function pad2(n) { return (n < 10 ? '0' : '') + n; }
function formatFechaDDMMYY(fecha) {
  return pad2(fecha.getDate()) + '/' + pad2(fecha.getMonth() + 1) + '/' + fecha.getFullYear();
}

function formatRangoFechasTexto(inicio, fin) {
  var MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  if (inicio.getMonth() === fin.getMonth()) {
    return 'Del ' + pad2(inicio.getDate()) + ' al ' + pad2(fin.getDate()) + ' de ' + MESES[inicio.getMonth()] + ' ' + inicio.getFullYear();
  } else {
    return 'Del ' + pad2(inicio.getDate()) + ' de ' + MESES[inicio.getMonth()] + ' al ' + pad2(fin.getDate()) + ' de ' + MESES[fin.getMonth()] + ' ' + inicio.getFullYear();
  }
}

var numeroSemanaActual = (d.numeroSemanaObjetivo !== undefined && d.numeroSemanaObjetivo !== null) ? d.numeroSemanaObjetivo : calcularNumeroSemana(hoy);
var rangoSemanaActual = calcularRangoSemana(numeroSemanaActual);
var rangoTexto = formatRangoFechasTexto(rangoSemanaActual.inicio, rangoSemanaActual.fin);

var ASIGNACION_SEMANAL = 1000;
var ASIGNACION_MENSUAL = 4000;

var catalogoReal = {};
