// semanal para que Taylor y demás maquinaria sin código digitado en la
// hoja se sumen correctamente al balance físico de la semana).
// ------------------------------------------------------------------
var EQUIPOS_FALLBACK_KEYWORDS = [
  { keywords: ['95LR'], codigo: 'V13-010', placaDefault: 'N/A', descDefault: 'Retroexcavadora New Holland 95LR' },
  { keywords: ['B110'], codigo: 'V13-011', placaDefault: 'N/A', descDefault: 'Retroexcavadora New Holland B110' },
  { keywords: ['310SJ', '310 SJ'], codigo: 'V13-012', placaDefault: 'N/A', descDefault: 'Retroexcavadora Jhon Deere 310SJ' },
  { keywords: ['RETRO CASE', 'RETROCASE', 'CASE 580', 'CASE580'], codigo: 'V13-013', placaDefault: 'N/A', descDefault: 'Retroexcavadora CAse 580M' },
  { keywords: ['43RVAX', '43R VAX'], codigo: 'V10-004', placaDefault: '43R-VAX', descDefault: 'Camioneta Pick up Ranger' }
];

function normalizarTextoBusqueda(t) {
  return String(t || '').toUpperCase()
    .replace(/[ÁÀÄÂ]/g, 'A').replace(/[ÉÈËÊ]/g, 'E').replace(/[ÍÌÏÎ]/g, 'I')
    .replace(/[ÓÒÖÔ]/g, 'O').replace(/[ÚÙÜÛ]/g, 'U').replace(/Ñ/g, 'N')
    .replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function buscarEquipoPorPlacaODescripcion(placaFila, descFila) {
  var placaNorm = normalizarPlaca(placaFila);
  var textoCombinado = normalizarTextoBusqueda(String(placaFila || '') + ' ' + String(descFila || ''));

  if (placaNorm) {
    var matchPorPlaca = Object.keys(catalogoReal).find(function(k) {
      return normalizarPlaca(catalogoReal[k].placa) === placaNorm;
    });
    if (matchPorPlaca) {
      return { codigo: matchPorPlaca, placa: catalogoReal[matchPorPlaca].placa, descripcion: catalogoReal[matchPorPlaca].descripcion };
    }
  }
  if (textoCombinado) {
    var matchPorDesc = Object.keys(catalogoReal).find(function(k) {
      var cd = normalizarTextoBusqueda(catalogoReal[k].descripcion);
      return cd && (textoCombinado.indexOf(cd) !== -1 || cd.indexOf(textoCombinado) !== -1);
    });
    if (matchPorDesc) {
      return { codigo: matchPorDesc, placa: catalogoReal[matchPorDesc].placa, descripcion: catalogoReal[matchPorDesc].descripcion };
    }
  }
  for (var i = 0; i < EQUIPOS_FALLBACK_KEYWORDS.length; i++) {
    var regla = EQUIPOS_FALLBACK_KEYWORDS[i];
    var coincide = regla.keywords.some(function(kw) { return textoCombinado.indexOf(kw) !== -1; });
    if (coincide) {
      var catInfo = catalogoReal[regla.codigo];
      return {
        codigo: regla.codigo,
        placa: (catInfo && catInfo.placa) || regla.placaDefault,
        descripcion: (catInfo && catInfo.descripcion) || regla.descDefault
      };
    }
  }
  return null;
}

function obtenerInfoEquipo(codigo, placaFila, descFila) {
  var cod = String(codigo || '').toUpperCase().trim();
  if (cod === 'N/D' || cod === 'N D' || cod === 'ND' || cod === '-') cod = '';
  var placa = placaFila && String(placaFila).trim() !== '---------' ? String(placaFila).trim() : '';
  var desc = descFila || '';

  if (cod && catalogoReal[cod]) {
    placa = catalogoReal[cod].placa || placa;
    desc = catalogoReal[cod].descripcion || desc;
  }

  if (!cod) {
    var encontrado = buscarEquipoPorPlacaODescripcion(placa || placaFila, desc || descFila);
    if (encontrado) {
      cod = encontrado.codigo;
      placa = encontrado.placa || placa;
      desc = encontrado.descripcion || desc;
    }
  }

  return { codigo: cod || 'N/D', placa: placa || 'N/A', descripcion: desc || 'Sin descripción' };
}

function grupoDeCodigo(cod) {
  return String(cod || '').toUpperCase().indexOf('V10-') === 0 ? 'GASOLINA' : 'GASOIL';
}

var consumoGasoilPorEquipo = {};
var consumoGasolinaPorEquipo = {};
Object.keys(catalogoReal).forEach(function(cod) {
  var cat = catalogoReal[cod];
  var destinoMapa = grupoDeCodigo(cod) === 'GASOLINA' ? consumoGasolinaPorEquipo : consumoGasoilPorEquipo;
  destinoMapa[cod] = { codigo: cod, descripcion: cat.descripcion, placa: cat.placa || 'N/A', total: 0, combustible: grupoDeCodigo(cod) };
});

var combInicialSemanaTotal = 0;
var destinosPorEquipo = {};
var registrosSurtidoES = [];
var ultimoDiaConCierre = null;
var combustibleRecibidoSemana = 0;
var combustibleRecibidoPrimerDia = 0;

var consumoPorDiaSemana = [0, 0, 0, 0, 0, 0, 0];
var consumoPorDiaSemanaGasolina = [0, 0, 0, 0, 0, 0, 0];

var diasDeEstaSemana = (d.diasProcesados || []).filter(function(dia) {
  var fechaObj = dia.fecha ? new Date(dia.fecha) : null;
  return fechaObj && calcularNumeroSemana(fechaObj) === numeroSemanaActual;
}).sort(function(a, b) {
  return new Date(a.fecha) - new Date(b.fecha);
});

diasDeEstaSemana.forEach(function(dia, diaIdx) {
  var fechaObj = new Date(dia.fecha);
  var esPrimerDia = (diaIdx === 0);
  var idxDia = Math.round((fechaObj.getTime() - rangoSemanaActual.inicio.getTime()) / 86400000);

  var sumaFinalDia = 0;
  var tieneCierreValido = false;

  (dia.tablas || []).forEach(function(tabla) {
    var esGasolina = (tabla.tipoCombustible === 'GASOLINA');
    var mapaConsumo = esGasolina ? consumoGasolinaPorEquipo : consumoGasoilPorEquipo;
    var etiquetaCombustible = esGasolina ? 'GASOLINA' : 'GASOIL';

    (tabla.filas || []).forEach(function(f) {
      var info = obtenerInfoEquipo(f.codigo, f.placas, f.descripcion);
      var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);

      if (!esGasolina) {
        if (esPrimerDia) {
          combInicialSemanaTotal += Number(f.combInicial) || 0;
        }
        if (Number(f.combFinal) > 0) {
          sumaFinalDia += Number(f.combFinal);
          tieneCierreValido = true;
        }
        var recibidoFila = (Number(f.surtCliente) || 0) + (Number(f.surtidoES) || 0);
        combustibleRecibidoSemana += recibidoFila;
        if (esPrimerDia) combustibleRecibidoPrimerDia += recibidoFila;
      }

      if (!esGasolina && Number(f.surtidoES) > 0) {
        registrosSurtidoES.push({
          fecha: formatFechaDDMMYY(fechaObj),
          codigo: info.codigo,
          placa: info.placa,
          cantidad: Number(f.surtidoES),
          estacion: 'E/S EXTERNA',
          destino: f.destino || 'BASE RX',
          combustible: 'GASOIL',
          obs: 'Surtido Autorizado E/S (Gasoil)'
        });
      }

      if (f.destino && f.destino !== '---------' && f.destino.trim() !== '') {
        if (!destinosPorEquipo[key]) destinosPorEquipo[key] = [];
        if (destinosPorEquipo[key].indexOf(f.destino.trim()) === -1) {
          destinosPorEquipo[key].push(f.destino.trim());
        }
      }

      var consumido = Number(f.combConsumido) || 0;
      if (idxDia >= 0 && idxDia <= 6) {
        if (!esGasolina) consumoPorDiaSemana[idxDia] += consumido;
        else consumoPorDiaSemanaGasolina[idxDia] += consumido;
      }

      if (mapaConsumo[key] || consumido > 0) {
        if (!mapaConsumo[key]) {
          mapaConsumo[key] = { codigo: info.codigo, descripcion: info.descripcion, placa: info.placa, total: 0, combustible: etiquetaCombustible };
        }
        mapaConsumo[key].total += consumido;
      }
    });
  });

  if (tieneCierreValido && !dia.tablas.some(function(t){ return t.diaNoCerrado; })) {
    ultimoDiaConCierre = sumaFinalDia;
  }
});

var semanaObjetivoHoja = (d.semanasProcesadas || []).find(function(s) { return s.numeroSemana === numeroSemanaActual; });
var seUsoRespaldoHojaSemanal = false;
if (semanaObjetivoHoja && diasDeEstaSemana.length === 0) {
  seUsoRespaldoHojaSemanal = true;
  var NOMBRES_DIAS_SEMANAL_SEM = ['LUNES', 'MARTES', 'MIERCOLES', 'JUEVES', 'VIERNES', 'SABADO', 'DOMINGO'];
  (semanaObjetivoHoja.filas || []).forEach(function(f) {
    var info = obtenerInfoEquipo(f.codigo, f.placas, f.descripcion);
    var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);
    var totalFila = Number(f.total) || 0;
    if (consumoGasoilPorEquipo[key] || totalFila > 0) {
      if (!consumoGasoilPorEquipo[key]) {
        consumoGasoilPorEquipo[key] = { codigo: info.codigo, descripcion: info.descripcion, placa: info.placa, total: 0, combustible: 'GASOIL' };
      }
      consumoGasoilPorEquipo[key].total += totalFila;
    }
    NOMBRES_DIAS_SEMANAL_SEM.forEach(function(nombreDia, idxDia) {
      var cant = (f.porDia && f.porDia[nombreDia]) ? Number(f.porDia[nombreDia]) : 0;
      if (idxDia >= 0 && idxDia <= 6) {
        consumoPorDiaSemana[idxDia] += cant;
      }
    });
  });
}

var surtidoESTotal = registrosSurtidoES.reduce(function(acc, r) { return acc + r.cantidad; }, 0);

var etiquetasDiasSemana = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'];
for (var i = 0; i < 7; i++) {
  var diaF = new Date(rangoSemanaActual.inicio.getTime() + i * 86400000);
  var nombresCortos = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
  etiquetasDiasSemana[i] = nombresCortos[diaF.getDay()] + ' ' + pad2(diaF.getDate());
}

var listaEquiposGasoil = Object.keys(consumoGasoilPorEquipo).map(function(key) {
  var e = consumoGasoilPorEquipo[key];
  var dests = destinosPorEquipo[key] || [];
  return {
    codigo: e.codigo,
    descripcion: e.descripcion,
    placa: e.placa,
    combustible: 'GASOIL',
    consumoSemana: Math.round(e.total * 10) / 10,
    destino: dests.length ? dests.join(' / ') : 'BASE RX'
  };
}).sort(function(a, b) { return b.consumoSemana - a.consumoSemana; });

var listaEquiposGasolina = Object.keys(consumoGasolinaPorEquipo).map(function(key) {
  var e = consumoGasolinaPorEquipo[key];
  var dests = destinosPorEquipo[key] || [];
  return {
    codigo: e.codigo,
    descripcion: e.descripcion,
    placa: e.placa,
    combustible: 'GASOLINA',
    consumoSemana: Math.round(e.total * 10) / 10,
    destino: dests.length ? dests.join(' / ') : 'BASE RX'
  };
}).sort(function(a, b) { return b.consumoSemana - a.consumoSemana; });

var consumoSemanalGasoil = listaEquiposGasoil.reduce(function(acc, e) { return acc + e.consumoSemana; }, 0);
var consumoSemanalGasolina = listaEquiposGasolina.reduce(function(acc, e) { return acc + e.consumoSemana; }, 0);

// ------------------------------------------------------------------
// REGLA FÍSICA OBLIGATORIA (CORRECCIÓN #1):
// combFinalSemana SIEMPRE se calcula por balance físico de inventario:
//   combFinalSemana = Math.max(0, combInicialSemana + surtidoESTotal - consumoSemanalGasoil)
// Ya NO se usa el último "combFinal" reportado en la hoja (ultimoDiaConCierre)
// para evitar descuadres entre el inventario físico real y lo digitado en planilla.
// ------------------------------------------------------------------
var combFinalCalculado = Math.max(0, combInicialSemanaTotal + surtidoESTotal - consumoSemanalGasoil);

var combInicialSinRecibos = Math.round((combInicialSemanaTotal - combustibleRecibidoPrimerDia) * 10) / 10;

return [{
  json: Object.assign({}, d, {
    modo: (d.modo === 'reporte_lunes_ejecutivo') ? 'reporte_lunes_ejecutivo' : 'reporte_semana',
    // Se preserva el origen automático (Schedule 18:00 VET) para el caption del informe.
    esReporteDiarioAuto: d.modo === 'reporte_diario_auto' || d.esReporteDiarioAuto === true,
    despachosESCount: registrosSurtidoES.length,
    tipoReporte: 'SEMANAL',
    numeroSemanaActual: numeroSemanaActual,
    rangoTexto: rangoTexto,
    combInicialSemana: Math.round(combInicialSemanaTotal * 10) / 10,
    combFinalSemana: Math.round(combFinalCalculado * 10) / 10,
    combustibleRecibidoSemana: Math.round(combustibleRecibidoSemana * 10) / 10,
    combustibleRecibidoPrimerDia: Math.round(combustibleRecibidoPrimerDia * 10) / 10,
    combInicialSinRecibos: combInicialSinRecibos,
    surtidoESTotal: Math.round(surtidoESTotal * 10) / 10,
    consumoSemanalActual: Math.round(consumoSemanalGasoil * 10) / 10,
    consumoSemanalGasoil: Math.round(consumoSemanalGasoil * 10) / 10,
    consumoSemanalGasolina: Math.round(consumoSemanalGasolina * 10) / 10,
    asignacionSemanal: ASIGNACION_SEMANAL,
    asignacionMensual: ASIGNACION_MENSUAL,
    equiposSemanal: listaEquiposGasoil.concat(listaEquiposGasolina),
    registrosSurtidoES: registrosSurtidoES,
    consumoPorDiaSemana: consumoPorDiaSemana.map(function(v) { return Math.round(v * 10) / 10; }),
    consumoPorDiaSemanaGasolina: consumoPorDiaSemanaGasolina.map(function(v) { return Math.round(v * 10) / 10; }),
    etiquetasDiasSemana: etiquetasDiasSemana,
    seUsoRespaldoHojaSemanal: seUsoRespaldoHojaSemanal
  })
}];

