var ALIAS_COLUMNAS = {
  CANT: ['CANT', 'CANT.', 'ITEM', 'N°', 'NO.', 'NRO'],
  DESCRIPCION: ['DESCRIPCION', 'DESCRIPCIÓN', 'EQUIPO', 'DESCRIPCION DEL EQUIPO'],
  CODIGO: ['CODIGO', 'CÓDIGO', 'COD', 'COD.'],
  PLACAS: ['PLACAS', 'PLACA'],
  COMB_DISP: ['COMB. DISP.', 'COMB DISP', 'COMBUSTIBLE DISPONIBLE'],
  SURT_PATIO: ['SURT. COMB. PATIO', 'SURT COMB PATIO', 'SURTIDO PATIO'],
  SURT_CLIENTE: ['SURT. COMB. CLIENTE', 'SURT COMB CLIENTE', 'SURTIDO CLIENTE'],
  COMB_INICIAL: ['COMB. INICIAL', 'COMBUSTIBLE INICIAL'],
  COMB_FINAL: ['COMB. FINAL', 'COMBUSTIBLE FINAL'],
  COMB_CONSUMIDO: ['COMB. CONSUMID (GASOIL)', 'COMB. CONSUMID (GASOLINA)', 'COMB. CONSUMIDO', 'COMBUSTIBLE CONSUMIDO'],
  SURTIDO_ES: ['SURTIDO DE COMB. E/S', 'SURTIDO E/S', 'SURTIDO ES'],
  COMB_TOTAL: ['COMB. TOTAL', 'COMBUSTIBLE TOTAL'],
  DESTINO: ['DESTINO', 'DESTINO / RUTA', 'RUTA']
};

function limpiarCelda(v) {
  return (v === undefined || v === null) ? '' : String(v).trim().toUpperCase();
}

function esFilaEncabezado(fila) {
  var tieneCantOCod = false, tieneDesc = false;
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (c === 'CANT' || c === 'CANT.' || c === 'CODIGO' || c === 'CÓDIGO') tieneCantOCod = true;
    if (c.indexOf('DESCRIPCION') === 0 || c.indexOf('DESCRIPCIÓN') === 0 || c === 'EQUIPO') tieneDesc = true;
  }
  return tieneCantOCod && tieneDesc;
}

function mapaColumnasDeFila(fila) {
  var mapa = {};
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (!c) continue;
    Object.keys(ALIAS_COLUMNAS).forEach(function(campo) {
      if (mapa[campo] !== undefined) return;
      if (ALIAS_COLUMNAS[campo].indexOf(c) !== -1) mapa[campo] = i;
    });
  }
  return mapa;
}

function tipoCombustibleDeEncabezado(fila) {
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (c.indexOf('GASOLINA') !== -1) return 'GASOLINA';
    if (c.indexOf('GASOIL') !== -1) return 'GASOIL';
  }
  return null;
}

function filaVacia(fila) {
  for (var i = 0; i < fila.length; i++) {
    if (limpiarCelda(fila[i]) !== '') return false;
  }
  return true;
}

function esFilaTotal(fila) {
  for (var i = 0; i < fila.length; i++) {
    var val = limpiarCelda(fila[i]);
    if (val === 'TOTAL' || val.indexOf('TOTAL ') === 0 || val.indexOf('TOTAL:') === 0) {
      return true;
    }
  }
  return false;
}

function numOr0(v) {
  var n = Number(v);
  return isNaN(n) ? 0 : n;
}

// ------------------------------------------------------------------
// BLINDAJE DE EQUIPOS SIN CÓDIGO (CORRECCIÓN #2)
// Se resuelve el código/placa/descripción del equipo lo más temprano
// posible en el pipeline (al consolidar las filas leídas del Excel),
// para que Taylor y demás maquinaria sin código digitado en la hoja
// lleguen ya identificados a todos los nodos de cálculo posteriores.
// ------------------------------------------------------------------
var catalogoReal = {};
try {
