      var pb = (b.mesNumeroArchivo === mesExcel ? 4 : 0) + (b.mesNumeroArchivo === mesCal ? 2 : 0);
      if (pb !== pa) return pb - pa;
      return pesoDatosDia(b) - pesoDatosDia(a);
