  });
  var resultado = sinNumero.slice();
  Object.keys(porNum).forEach(function(k) {
    var copias = porNum[k];
    if (copias.length === 1) { resultado.push(copias[0]); return; }
    var mesExcel = mesExcelDeSemanaCons(Number(k));
    copias.sort(function(a, b) {
      var pa = a.mesNumeroArchivo === mesExcel ? 1 : 0;
