}

// Generador 100% dinámico de botones por trimestre:
function generarTecladoTrimestre(inicio, fin) {
  var teclado = [];
  var fila = [];
  for (var s = inicio; s <= fin; s++) {
    var label = 'Sem ' + s;
    if (s === semanaActualNum) label += ' (Actual)';
    fila.push({ text: label, callback_data: '/semana ' + s });
    if (fila.length === 4 || s === fin) {
      if (fila.length === 1 && s === fin) {
        fila.push({ text: '⬅️ Volver a Semanas', callback_data: '/menu_semanas' });
        teclado.push(fila);
        fila = [];
      } else {
        teclado.push(fila);
        fila = [];
      }
    }
  }
  if (fila.length > 0) {
    fila.push({ text: '⬅️ Volver a Semanas', callback_data: '/menu_semanas' });
    teclado.push(fila);
  }
  return { inline_keyboard: teclado };
}

